// // // // // // // // // // // // // // // // // // // // // // //                       boxShadow:    getShadow(isActive, project.accent),
// // // // // // // // // // // // // // // // // // // // // // //                       minHeight:    `${cardMinHeight}px`,
// // // // // // // // // // // // // // // // // // // // // // //                       // FIX 2 cont.: square corners on mobile for true edge-to-edge feel
